// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint64 timestamp, uint64 blockNumber) public {
        // Bound inputs to realistic values
        vm.assume(amount >= 1 ether && amount <= 100 ether);
        vm.assume(timestamp > 0);
        vm.assume(blockNumber > 0);

        // Set block parameters
        vm.warp(timestamp);
        vm.roll(blockNumber);

        // Deal ether to this contract to send
        vm.deal(address(this), amount);

        // Call fallback with the given amount
        (bool success, ) = address(c).call{value: amount}("");

        // If the call succeeded, check the invariant
        if (success) {
            uint256 balance = address(c).balance;
            if (blockNumber % 15 == 0) {
                assertTrue(balance == 0, "Balance should be 0 when block number is multiple of 15");
            } else {
                assertTrue(balance % 10 ether == 0, "Balance should be a multiple of 10 ether");
            }
        }
    }
}

